<script>
(function(){
  const destinationInput=document.getElementById('destinationInput');
  const destinationPop=document.getElementById('destinationPop');
  const clearButton=document.getElementById('clearDestination');
  const calendarPop=document.getElementById('calendarPop');
  const guestsPop=document.getElementById('guestsPop');
  const dateInput=document.getElementById('dateInput');
  let selectedStart=null,selectedEnd=null,monthOffset=0;
  const counts={adults:2,children:0,rooms:1};
  function closePopovers(except){
    [destinationPop,calendarPop,guestsPop].forEach(p=>{if(p!==except)p.classList.remove('open')});
  }
  destinationInput.addEventListener('focus',()=>{closePopovers(destinationPop);destinationPop.classList.add('open')});
  destinationInput.addEventListener('input',()=>{destinationPop.classList.add('open');clearButton.style.display=destinationInput.value?'block':'none'});
  clearButton.addEventListener('click',()=>{destinationInput.value='';clearButton.style.display='none';destinationInput.focus()});
  document.querySelectorAll('.dest-option').forEach(option=>option.addEventListener('click',()=>{
    destinationInput.value=option.dataset.place;clearButton.style.display='block';destinationPop.classList.remove('open');
  }));
  document.getElementById('dateField').addEventListener('click',e=>{
    if(e.target.closest('.calendar-pop'))return;
    closePopovers(calendarPop);calendarPop.classList.toggle('open');renderMonths();
  });
  document.getElementById('guestField').addEventListener('click',e=>{
    if(e.target.closest('.guests-pop'))return;
    closePopovers(guestsPop);guestsPop.classList.toggle('open');
  });
  document.querySelectorAll('.counter button').forEach(button=>button.addEventListener('click',e=>{
    e.stopPropagation();
    const key=button.dataset.count;
    counts[key]=Math.max(key==='adults'||key==='rooms'?1:0,counts[key]+Number(button.dataset.delta));
    document.getElementById(key+'Count').textContent=counts[key];updateGuests();
  }));
  function updateGuests(){
    document.getElementById('guestSummary').value=counts.adults+' adults · '+counts.children+' children · '+counts.rooms+' room'+(counts.rooms===1?'':'s');
  }
  document.getElementById('calendarTab').addEventListener('click',()=>setCalendarTab(true));
  document.getElementById('flexTab').addEventListener('click',()=>setCalendarTab(false));
  function setCalendarTab(show){
    document.getElementById('calendarTab').classList.toggle('active',show);
    document.getElementById('flexTab').classList.toggle('active',!show);
    document.getElementById('calendarView').style.display=show?'block':'none';
    document.getElementById('flexView').style.display=show?'none':'block';
  }
  function renderMonths(){
    const holder=document.getElementById('months');holder.innerHTML='';
    for(let i=0;i<2;i++){
      const dt=new Date(2025,7+monthOffset+i,1);
      const monthName=dt.toLocaleString('en-US',{month:'long'});
      const year=dt.getFullYear();
      const panel=document.createElement('div');
      const head=document.createElement('div');head.className='month-head';
      const prev=document.createElement('button');prev.className='btn';prev.textContent=i===0?'‹':'';
      prev.addEventListener('click',()=>{monthOffset--;renderMonths()});
      const title=document.createElement('span');title.textContent=monthName+' '+year;
      const next=document.createElement('button');next.className='btn';next.textContent=i===1?'›':'';
      next.addEventListener('click',()=>{monthOffset++;renderMonths()});
      head.append(prev,title,next);panel.appendChild(head);
      const week=document.createElement('div');week.className='week';
      ['Su','Mo','Tu','We','Th','Fr','Sa'].forEach(d=>{const s=document.createElement('span');s.textContent=d;week.appendChild(s)});
      panel.appendChild(week);
      const days=document.createElement('div');days.className='days';
      const start=dt.getDay(),num=new Date(year,dt.getMonth()+1,0).getDate();
      for(let j=0;j<start;j++){const blank=document.createElement('button');blank.className='day muted';blank.textContent='';days.appendChild(blank)}
      for(let day=1;day<=num;day++){
        const b=document.createElement('button');b.className='day btn';b.textContent=day;
        const date=new Date(year,dt.getMonth(),day);
        if(selectedStart&&date.getTime()===selectedStart.getTime())b.classList.add('chosen');
        if(selectedEnd&&date.getTime()===selectedEnd.getTime())b.classList.add('chosen');
        if(selectedStart&&selectedEnd&&date>selectedStart&&date<selectedEnd)b.classList.add('range');
        b.addEventListener('click',()=>{
          if(!selectedStart||selectedEnd){selectedStart=date;selectedEnd=null}
          else if(date<selectedStart){selectedStart=date}
          else selectedEnd=date;
          updateDates();renderMonths();
        });
        days.appendChild(b);
      }
      panel.appendChild(days);holder.appendChild(panel);
    }
  }
  function updateDates(){
    if(!selectedStart){dateInput.value='Check-in date  —  Check-out date';return}
    const format=d=>d.toLocaleString('en-US',{month:'short'})+' '+d.getDate();
    dateInput.value=format(selectedStart)+(selectedEnd?'  —  '+format(selectedEnd):'  —  Check-out date');
  }
  document.addEventListener('click',e=>{
    if(!e.target.closest('.search-area'))closePopovers(null);
  });
  document.querySelector('.search-submit').addEventListener('click',()=>closePopovers(null));
  renderMonths();
})();
</script>
</body>
